type Role = 'City Command Center' | 'Transport Authority' | 'Traffic & Police' | 'Road Infrastructure';
type Severity = 'Critical' | 'High' | 'Medium' | 'Low';
type IncidentStatus = 'New' | 'Investigating' | 'Repair initiated' | 'Verified';

type Bus = {
  id: string; route: string; location: string; status: 'Active' | 'Offline' | 'Paused'; cameras: string; edge: string; privacy: string; model: string; last: string; direction: string;
};
type Incident = {
  id: string; type: string; severity: Severity; location: string; time: string; bus: string; confidence: number; status: IncidentStatus; category: 'Road' | 'Traffic' | 'Safety' | 'Infrastructure'; gps: string;
};

const routes = ['305', '218', '312', '424', 'A-1', '70', '27', '422', '415', 'C-21', 'S-45', '18'];
const places = ['S.V. Road', 'Bandra', 'Dadar', 'Kurla', 'Andheri', 'Powai', 'BKC', 'Borivali', 'Worli', 'Ghatkopar', 'Chembur', 'Vikhroli'];
const buses: Bus[] = Array.from({ length: 24 }, (_, i) => {
  const n = [142, 217, 304, 118, 102, 127, 143, 156, 171, 188, 193, 204, 229, 238, 246, 252, 267, 281, 298, 315, 326, 341, 356, 368][i];
  return { id: `BUS-${n}`, route: routes[i % routes.length], location: places[i % places.length], status: i === 19 || i === 22 ? 'Offline' : i === 8 ? 'Paused' : 'Active', cameras: i % 7 === 0 ? '5/6' : '6/6', edge: i === 19 ? 'Standby' : 'Active', privacy: 'Protected', model: `v1.${12 - (i % 3)}`, last: i === 19 ? '42 min ago' : `${2 + (i % 11)} min ago`, direction: i % 2 ? 'Northbound' : 'Southbound' };
});

